-- stage 2: Acceleration Position
INSERT INTO public.development_pathway_stages
  (pathway_id, stage_number, stage_key, name, objective, why_it_matters,
   mastery_signals, common_failure_modes, coaching_emphasis,
   estimated_practices_min, estimated_practices_max, notes)
SELECT p.id,
  2, 'acceleration-position', 'Acceleration Position',
  'Project the body forward and push into the ground for the first few steps instead of standing straight up.',
  'Almost every sprint in baseball is over in ten to twenty yards, so the acceleration phase is not the start of the race — it is the whole race. A player who pops upright on the first step has spent the only part that mattered.',
  ARRAY['Does not pop upright on the first step', 'First three steps project the body forward', 'No excessive reaching with the front foot', 'Holds a consistent forward body angle out of a falling start'],
  ARRAY['Bending at the waist instead of leaning from the ankles', 'Hips sagging or piking in the wall drive, so the lean is not a straight line', 'Running the acceleration reps too close together, which turns them into conditioning'],
  'Rest is part of the drill. Five hard ten-yard sprints with a real walk-back teach more than fifteen crammed together, and the crammed version teaches the body to run slowly.',
  2, 4,
  NULL
FROM public.development_pathways p WHERE p.slug = 'speed-and-agility-development';

