-- stage 3: First-Step Explosion
INSERT INTO public.development_pathway_stages
  (pathway_id, stage_number, stage_key, name, objective, why_it_matters,
   mastery_signals, common_failure_modes, coaching_emphasis,
   estimated_practices_min, estimated_practices_max, notes)
SELECT p.id,
  3, 'first-step-explosion', 'First-Step Explosion',
  'React and move without a wasted step, gaining ground on the very first one.',
  'A false step costs about a third of a second, which is roughly a stride and a half — the exact margin between a ball fielded and a ball through the gap, or a stolen base and an out. Almost every young player takes one, and almost none of them know they do.',
  ARRAY['No false step on four of five quality reps', 'First step gains meaningful ground', 'Reacts quickly without standing straight up', 'Can repeat clean starts from more than one athletic position'],
  ARRAY['A small backward or sideways step before going forward', 'Weight settled on the heels in the ready position, which makes a false step unavoidable', 'Anticipating a rhythm rather than reacting to the signal'],
  'Watch the feet from the side. A false step is invisible from the front and a player cannot feel their own — being told it happened, every time, fixes it faster than any drill.',
  3, 5,
  NULL
FROM public.development_pathways p WHERE p.slug = 'speed-and-agility-development';

