-- stage 4: Elasticity & Quick Ground Contact
INSERT INTO public.development_pathway_stages
  (pathway_id, stage_number, stage_key, name, objective, why_it_matters,
   mastery_signals, common_failure_modes, coaching_emphasis,
   estimated_practices_min, estimated_practices_max, notes)
SELECT p.id,
  4, 'elasticity', 'Elasticity & Quick Ground Contact',
  'Leave the ground quickly and land under control, with quiet, springy contacts.',
  'Time spent on the ground is time not spent moving. The player who looks springy and the player who looks heavy are usually not separated by strength but by how long each foot stays down, and that is trainable at this age with very little volume.',
  ARRAY['Pogo contacts are quick and quiet rather than heavy', 'Maintains a tall posture through a set of pogos', 'Sticks a broad-jump landing and holds it for a two-count', 'Keeps a steady jump-rope rhythm for thirty seconds'],
  ARRAY['Squatting and jumping instead of bouncing from the ankles', 'Landing flat and loud', 'Adding sets — this is coordination work for children, not adult plyometric volume'],
  'Keep it short on purpose. Three sets of ten to fifteen contacts is the whole stage; the third sloppy set is worse than not doing it, and fatigue here is what turns a coordination drill into an injury risk.',
  2, 4,
  NULL
FROM public.development_pathways p WHERE p.slug = 'speed-and-agility-development';

