-- stage 5: Deceleration
INSERT INTO public.development_pathway_stages
  (pathway_id, stage_number, stage_key, name, objective, why_it_matters,
   mastery_signals, common_failure_modes, coaching_emphasis,
   estimated_practices_min, estimated_practices_max, notes)
SELECT p.id,
  5, 'deceleration', 'Deceleration',
  'Stop under control from a sprint, with the hips down and without extra steps.',
  'Taught before change of direction on purpose. A player who cannot stop cannot safely turn, and a cut is nothing more than a stop with an exit attached. It is also the least-coached quality in youth baseball and the one most associated with knee injuries later.',
  ARRAY['Lowers the hips into the stop instead of staying tall', 'Stops within about a yard of the target without extra steps', 'Avoids straight-leg braking', 'Holds a balanced position for a two-count after stopping'],
  ARRAY['Staying tall and stiff-legging the stop, putting the load through the knee', 'Knees caving inward on the snap down', 'Adding speed before the stop is genuinely under control'],
  'This is the one stage to be deliberately conservative in. Build speed up across the session rather than starting at full effort — an out-of-control stop is exactly the mechanism that hurts young knees.',
  2, 4,
  NULL
FROM public.development_pathways p WHERE p.slug = 'speed-and-agility-development';

