-- stage 6: Change of Direction
INSERT INTO public.development_pathway_stages
  (pathway_id, stage_number, stage_key, name, objective, why_it_matters,
   mastery_signals, common_failure_modes, coaching_emphasis,
   estimated_practices_min, estimated_practices_max, notes)
SELECT p.id,
  6, 'change-of-direction', 'Change of Direction',
  'Plant once, redirect, and accelerate out of the turn.',
  'Baseball is played in short bursts that almost never go in a straight line. A fielder who takes three setup steps before changing direction has given up more ground than any amount of top-end speed will get back.',
  ARRAY['Uses one decisive plant rather than several setup steps', 'Hips turn toward the new direction quickly', 'Exits the cut accelerating rather than drifting', 'Stays balanced through the plant'],
  ARRAY['Rounding the cut into a comfortable arc', 'Planting the inside foot, which forces an extra step', 'Standing tall through the plant, leaving nothing to push with'],
  'Watch the plant foot, not the body. Cutting left means planting right, and a player planting the wrong foot will look busy and slow without either of you knowing why.',
  3, 5,
  NULL
FROM public.development_pathways p WHERE p.slug = 'speed-and-agility-development';

