-- stage 10: Game-Speed Integration & Retest
INSERT INTO public.development_pathway_stages
  (pathway_id, stage_number, stage_key, name, objective, why_it_matters,
   mastery_signals, common_failure_modes, coaching_emphasis,
   estimated_practices_min, estimated_practices_max, notes)
SELECT p.id,
  10, 'game-speed-and-retest', 'Game-Speed Integration & Retest',
  'Hold the movement together under competitive pressure, and repeat the baseline measurements.',
  'Technique that only survives a drill has not transferred. This stage puts the player in a race and in a game read, then takes the four numbers again — not to pass or fail them, but to give the coach something to look at alongside what they have been watching for weeks.',
  ARRAY['Movement quality holds up under reaction pressure', 'Technique stays intact at full speed', 'All four measurements repeated under the same conditions as the baseline', 'Coach has decided whether the pathway is complete or worth recycling into specific stages'],
  ARRAY['Mechanics falling apart as soon as the drill becomes a competition', 'Treating a faster time as proof and a slower one as failure, when a stopwatch in a parent''s hand is not that precise', 'Retesting tired, at the end of a practice, and comparing it to a baseline taken fresh'],
  'Do NOT require every number to improve before completing the pathway. A child who grew two inches mid-season can move better and time slower. The measurements inform the decision; the coach makes it.',
  1, 3,
  NULL
FROM public.development_pathways p WHERE p.slug = 'speed-and-agility-development';

