COMMIT;

-- ── verification ────────────────────────────────────────────────────────
SELECT
  (SELECT count(*) FROM public.development_pathways WHERE slug = 'speed-and-agility-development')    AS pathway,
  (SELECT count(*) FROM public.development_pathway_stages s
     JOIN public.development_pathways p ON p.id = s.pathway_id
     WHERE p.slug = 'speed-and-agility-development')                                                  AS stages,
  (SELECT count(*) FROM public.development_pathway_stage_drills sd
     JOIN public.development_pathway_stages s ON s.id = sd.stage_id
     JOIN public.development_pathways p ON p.id = s.pathway_id
     WHERE p.slug = 'speed-and-agility-development')                                                  AS stage_drills,
  (SELECT count(*) FROM public.drill_resources WHERE source = 'benchcoach_original'
     AND skill_category = 'Athletic Development')                                            AS movement_drills,
  (SELECT count(*) FROM public.drill_resources)                                              AS drills_total;
